{
  "findings": [
    {
      "check_id": "CKV_AZURE_26",
      "title": "Ensure that 'Send Alerts To' is enabled for MSSQL servers",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The MSSQL server security alert policy is missing email addresses for notification, which means nobody will be promptly alerted in case of a threat being detected."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  email_addresses            = []\n  disabled_alerts = [\n    \"Sql_Injection\",\n    \"Data_Exfiltration\"\n  ]\n  retention_days = 20\n}",
  "fix_summary": "Added 'email_addresses' attribute to the MSSQL server security alert policy to enable 'Send Alerts To'."
}
